export const ARENAS=[{id:'city',name:'New York',label:'ŞEHİR ÇATILARI',desc:'Teknoloji ve zekâ saldırıları %10 güçlenir.',boost:[1,4],color:'#d97949'}, {id:'asgard',name:'Asgard',label:'GÖKKUŞAĞI KÖPRÜSÜ',desc:'Güç ve enerji saldırıları %10 güçlenir.',boost:[0,5],color:'#ab91d5'}, {id:'wakanda',name:'Wakanda',label:'VİBRANYUM VADİSİ',desc:'Dayanıklılık ve hız %10 güçlenir.',boost:[2,3],color:'#7fa899'}];
export const hero=id=>HEROES.find(h=>h.id===id);
export function shuffle(items,rng=Math.random){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
export function newGame(names=['Oyuncu 1','Oyuncu 2'],mode='local',rng=Math.random){return {version:1,mode,players:names.map((name,i)=>({name:name.trim().slice(0,20)||`Oyuncu ${i+1}`,coins:20,team:[]})),pool:shuffle(HEROES,rng).slice(0,10).map(h=>h.id),round:0,turn:0,bid:0,leader:null,passes:0,phase:'auction',history:[],arena:'city',luck:12};}
export function canBid(g,p,amount){return g.phase==='auction'&&p===g.turn&&p!==g.leader&&g.players[p].team.length<5&&Number.isInteger(amount)&&amount>g.bid&&amount<=g.players[p].coins;}
export function bid(g,amount){if(!canBid(g,g.turn,amount))return false;g.bid=amount;g.leader=g.turn;g.passes=0;g.turn=1-g.turn;return true;}
export function pass(g){if(g.phase!=='auction')return false;if(g.leader!==null){finishLot(g,g.leader);}else{g.passes++;if(g.passes>=2)finishLot(g,null);else g.turn=1-g.turn;}return true;}
function finishLot(g,winner){const id=g.pool[g.round];if(winner!==null){g.players[winner].coins-=g.bid;g.players[winner].team.push(id);}g.history.push({id,winner,price:winner===null?0:g.bid});g.round++;g.bid=0;g.leader=null;g.passes=0;g.turn=g.round%2;if(g.round>=10||g.players.every(p=>p.team.length===5)){g.phase='ready';for(let p=0;p<2;p++){if(!g.players[p].team.length){const used=g.players.flatMap(x=>x.team);const free=g.pool.find(id=>!used.includes(id));g.players[p].team.push(free);g.history.push({id:free,winner:p,price:0,reinforcement:true});}}}}
export function synergy(ids){const counts={};ids.forEach(id=>counts[hero(id).group]=(counts[hero(id).group]||0)+1);return Math.min(12,Object.values(counts).reduce((a,n)=>a+Math.max(0,n-1)*4,0));}
export function botDecision(g,rng=Math.random){const h=hero(g.pool[g.round]);const p=g.players[1];const remaining=Math.max(1,Math.min(5-p.team.length,10-g.round));const value=Math.max(2,Math.round(h.rating/15+(rng()-.5)*3));const max=Math.min(p.coins,Math.max(1,Math.round(p.coins/remaining)+2),value);return canBid(g,1,g.bid+1)&&g.bid<max?g.bid+1:null;}
export function createBattle(g,rng=Math.random){const arena=ARENAS.find(a=>a.id===g.arena)||ARENAS[0];const fighters=g.players.map((p,side)=>p.team.map(id=>{const h=hero(id);const stats=h.stats.map((n,i)=>n*(arena.boost.includes(i)?1.1:1));const maxHp=Math.round(65+stats[3]*12);return {id,side,stats,hp:maxHp,maxHp,shield:0,weaken:false,actions:0,synergy:synergy(p.team)};}));return {fighters,round:0,queue:[],done:false,winner:null,events:[],rng,luck:Math.min(25,Math.max(0,g.luck))/100};}
export function battleStep(b){if(b.done)return null;const living=s=>b.fighters[s].filter(f=>f.hp>0);if(!b.queue.length){b.round++;b.queue=b.fighters.flat().filter(f=>f.hp>0).map(f=>({f,initiative:f.stats[2]+f.stats[1]*.15+b.rng()*2})).sort((a,c)=>c.initiative-a.initiative).map(x=>x.f);}
let attacker=b.queue.shift();while(attacker&&attacker.hp<=0)attacker=b.queue.shift();if(!attacker)return battleStep(b);const opponents=living(1-attacker.side);const target=opponents[Math.floor(b.rng()*opponents.length)];if(!target){finish();return null;}attacker.actions++;const special=attacker.actions%3===0;const h=hero(attacker.id);const crit=b.rng()<b.luck;const dodge=b.rng()<Math.min(.16,Math.max(.02,(target.stats[2]-attacker.stats[1])*.012+.04));const variance=1+(b.rng()*2-1)*b.luck;let raw=(attacker.stats[0]*1.5+attacker.stats[5]*1.15+attacker.stats[4]*.65+attacker.stats[1]*.4+7)*(1+attacker.synergy/100);if(attacker.id==='hulk')raw*=1+(1-attacker.hp/attacker.maxHp)*.3;if(attacker.weaken){raw*=.65;attacker.weaken=false;}const pierce=special&&h.ability==='pierce';let damage=dodge?0:Math.max(5,Math.round((raw-target.stats[3]*(pierce?.3:.9))*variance*(crit?1.5:1)*(special?1.25:1)));const absorbed=Math.min(target.shield,damage);target.shield-=absorbed;damage-=absorbed;target.hp=Math.max(0,target.hp-damage);const extras=[];
if(special&&!dodge){if(h.ability==='heal'){const heal=Math.min(24,attacker.maxHp-attacker.hp);attacker.hp+=heal;extras.push(`${h.name} +${heal} can yeniledi`);}if(h.ability==='shield'){living(attacker.side).forEach(f=>f.shield=Math.min(40,f.shield+15));extras.push('Takıma +15 kalkan');}if(h.ability==='weaken'&&target.hp>0){target.weaken=true;extras.push('Hedefin sonraki saldırısı −%35');}if(h.ability==='aoe'){opponents.filter(f=>f!==target&&f.hp>0).forEach(f=>{const d=Math.round(8+attacker.stats[5]);const a=Math.min(d,f.shield);f.shield-=a;f.hp=Math.max(0,f.hp-(d-a));});extras.push('Alan hasarı diğer rakiplere yayıldı');}}
const event={round:b.round,attacker:attacker.id,side:attacker.side,target:target.id,damage,crit:crit&&!dodge,dodge,special:special&&!dodge,skill:h.skill,extras,knockout:target.hp===0};b.events.push(event);finish();return event;
function finish(){const alive=b.fighters.map((_,s)=>living(s).length);if(alive.includes(0)){b.done=true;b.winner=alive[0]>0?0:alive[1]>0?1:null;}else if(b.round>=40&&!b.queue.length){const health=b.fighters.map(fs=>fs.reduce((a,f)=>a+f.hp,0)/fs.reduce((a,f)=>a+f.maxHp,0));b.done=true;b.winner=Math.abs(health[0]-health[1])<.00001?null:health[0]>health[1]?0:1;b.decision=true;}}}
